def calculate_S(N):
    S = 0
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            S += (a * b) // (N + 1)
    return S

def calculate_T(N):
    # T(N) = (N^3 - N^2 + 2) / 4
    return (N**3 - N**2 + 2) / 4

results = {}
for N in [1, 2, 3, 4]:
    S_N = calculate_S(N)
    T_N = calculate_T(N)
    results[N] = {'S(N)': S_N, 'T(N)': T_N}

for N, res in results.items():
    print(f"N={N}: S(N) = {res['S(N)']}, T(N) = {res['T(N)']}")

